		void CreateInitialTransfer()
		{
			var order = VASOrder;
			if (order != null)
			{
				var transfer = order.GetOrCreateInitialTransfer(this);
				if (transfer != null)
				{
					var savedSuccessFully = transfer.IsInDatabase || FireSaveButton() == ContinueWithSave.Yes;
					if (savedSuccessFully)
					{
						ShowTransferFormModally(transfer);
					}
				}
			}
		}

