		#region FinaliseButton_Click

		void FinaliseButton_Click(object sender, EventArgs e)
		{
			var vasOrder = VASOrder;
			if (vasOrder != null)
			{
				if (vasOrder.FinaliseVASOrder(this))
				{
					FireSaveButton();
				}
				else
				{
					ExposeServiceTabPageNotifications();
				}
			}
		}

		void ExposeServiceTabPageNotifications()
		{
			if (VASOrder.Services.Cast<WhsJobService>().Any(s => s.ES_CompletedDateTimeOffsetInfo.HasErrors()))
			{
				TabPageNotificationsExposer.ExposeTabPageNotifications(this, VASOrder);
			}
		}

