		#region MarkVASOrderCompletedButton_Click

		void MarkVASOrderCompletedButton_Click(object sender, EventArgs e)
		{
			MarkVASOrderAsCompleted();
		}

		void MarkVASOrderAsCompleted()
		{
			var vasOrder = VASOrder;
			if (vasOrder != null)
			{
				if (vasOrder.WVO_WorkCompletedTimeUtc.IsValid)
				{
					CreateReturnTransfer(vasOrder);
				}
				else if (vasOrder.MarkVASOrderAsCompleted(this))
				{
					UpdateMarkVASOrderCompletedButtonText();
					var caption = Res.GetString("568187b9-17e1-47f8-be83-0898544b825b", "Successfully Completed");
					var message = Res.GetString("ea3766c4-6554-4804-82fd-83b4bcc14a58", "Successfully Completed the VAS Order.");
					Globals.Message.ShowInformation(message, caption);
				}
			}
		}

		void CreateReturnTransfer(WhsVASOrder vasOrder)
		{
			var returnTransfer = vasOrder.GetOrCreateReturnTransfer(this);
			if (returnTransfer != null)
			{
				if (returnTransfer.IsInDatabase)
				{
					ShowTransferFormModally(returnTransfer);
				}
				else
				{
					UpdateMarkVASOrderCompletedButtonText();
					var caption = Res.GetString("0775eb26-4d6c-4146-86b8-a47ab7a65021", "Save VAS Order");
					var message = Res.GetString("f681dc3f-3de0-437f-9259-399425a06cb7", "Save the VAS Order before viewing the Transfer Out.");
					Globals.Message.ShowInformation(message, caption);
				}
			}
			else
			{
				ExposeServiceTabPageNotifications();
			}
		}

		#endregion

