		void UpdateButtonsReadOnly()
		{
			var vasOrder = VASOrder;
			if (vasOrder != null)
			{
				var buttonsEnabled = !vasOrder.IsCancelled;
				MarkVASOrderCompletedButton.Enabled = buttonsEnabled;
				CreateInitialTransferButton.Enabled = buttonsEnabled;
				FinaliseButton.Enabled = buttonsEnabled;
			}
		}

		void UpdateMarkVASOrderCompletedButtonText()
		{
			var vasOrder = VASOrder;
			if (vasOrder != null)
			{
				if (vasOrder.TransferOutOfServiceArea != null)
				{
					MarkVASOrderCompletedButton.CaptionResourceString = Res.GetData("VASOrderEntryForm|MarkVASOrderCompletedButton", "View Transfer Out");
					MarkVASOrderCompletedButton.UpdateCaption();
				}
				else if (vasOrder.WVO_WorkCompletedTimeUtc.IsValid)
				{
					MarkVASOrderCompletedButton.CaptionResourceString = Res.GetData("VASOrderEntryForm|CreateTranferOutButton", "Create Transfer Out");
					MarkVASOrderCompletedButton.UpdateCaption();
				}
			}
		}

